import React, { useState, useEffect } from "react";
import { useAuth } from "../context/AuthContext";
import { userAPI, petsAPI, adminAPI } from "../services/api";
import { useNavigate } from "react-router-dom";

// Helper function to get full image URL
const getImageUrl = (imagePath) => {
  if (!imagePath) return "/default-pet.png";
  if (imagePath.startsWith("http")) return imagePath;
  return `http://localhost:8000${imagePath}`;
};

const AdminDashboard = () => {
  const { user, logout } = useAuth();
  const navigate = useNavigate();
  
  console.log("AdminDashboard rendered. User:", user);
  
  // State management
  const [activeTab, setActiveTab] = useState("dashboard");
  const [activePendingTab, setActivePendingTab] = useState("lost-reports"); // Sub-tab for pending requests
  const [activeRecordsTab, setActiveRecordsTab] = useState("all-lost"); // Sub-tab for all records
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [successMessage, setSuccessMessage] = useState("");
  
  // Dashboard Stats (comprehensive)
  const [dashboardStats, setDashboardStats] = useState(null);
  
  // Pending Requests (all types)
  const [pendingLostReports, setPendingLostReports] = useState([]);
  const [pendingFoundReports, setPendingFoundReports] = useState([]);
  const [pendingAdoptionRequests, setPendingAdoptionRequests] = useState([]);
  const [pendingAdoptionPosts, setPendingAdoptionPosts] = useState([]);
  
  // All Records by Status
  const [allLostPets, setAllLostPets] = useState([]);
  const [allFoundPets, setAllFoundPets] = useState([]);
  const [allAdoptedPets, setAllAdoptedPets] = useState([]);
  const [allAvailablePets, setAllAvailablePets] = useState([]);
  
  // Search and Filter
  const [searchQuery, setSearchQuery] = useState("");
  const [filterType, setFilterType] = useState("all");
  const [filterStatus, setFilterStatus] = useState("all");
  const [filterGender, setFilterGender] = useState("");
  const [filterBreed, setFilterBreed] = useState("");
  const [filterLocation, setFilterLocation] = useState("");
  const [filterReportStatus, setFilterReportStatus] = useState("accepted");
  const [searchResults, setSearchResults] = useState([]);
  const [searchLoading, setSearchLoading] = useState(false);
  const [hasSearched, setHasSearched] = useState(false);
  
  // Notifications
  const [notifications, setNotifications] = useState([]);
  const [showNotifications, setShowNotifications] = useState(false);
  const [unreadCount, setUnreadCount] = useState(0);
  
  // Detail Modal
  const [showDetailModal, setShowDetailModal] = useState(false);
  const [selectedItem, setSelectedItem] = useState(null);
  const [detailLoading, setDetailLoading] = useState(false);
  const [modalType, setModalType] = useState(""); // 'report' or 'adoption'
  
  // Profile Dropdown
  const [showProfileDropdown, setShowProfileDropdown] = useState(false);

  // Notification Detail Modal
  const [showNotificationModal, setShowNotificationModal] = useState(false);
  const [selectedNotification, setSelectedNotification] = useState(null);

  // Profile Edit State
  const [profileData, setProfileData] = useState({
    first_name: "",
    last_name: "",
    email: "",
    phone_no: "",
    address: "",
    city: "",
    state: "",
    pincode: "",
    gender: "",
    profile_picture: null,
  });
  const [isEditingProfile, setIsEditingProfile] = useState(false);
  const [profileImage, setProfileImage] = useState(null);
  const [profileImagePreview, setProfileImagePreview] = useState(null);
  const [submitLoading, setSubmitLoading] = useState(false);

  // Check if user is admin
  useEffect(() => {
    console.log("Admin check - User role:", user?.role);
    if (user && user.role !== 'admin') {
      console.log("Not admin, redirecting to /dashboard");
      navigate('/dashboard');
    }
  }, [user, navigate]);

  // Load initial data
  useEffect(() => {
    console.log("Load data effect - User role:", user?.role);
    if (user?.role === 'admin') {
      console.log("Loading admin data...");
      loadAllData();
    }
  }, [user]);

  // Auto-hide messages
  useEffect(() => {
    if (error) {
      const timer = setTimeout(() => setError(""), 5000);
      return () => clearTimeout(timer);
    }
  }, [error]);

  useEffect(() => {
    if (successMessage) {
      const timer = setTimeout(() => setSuccessMessage(""), 5000);
      return () => clearTimeout(timer);
    }
  }, [successMessage]);

  const loadAllData = async () => {
    console.log("loadAllData started");
    setLoading(true);
    try {
      await Promise.all([
        loadDashboardStats(),
        loadPendingReports(),
        loadPendingAdoptions(),
        loadAllPets(),
        loadNotifications(),
      ]);
      console.log("loadAllData completed successfully");
    } catch (err) {
      console.error("Error loading admin data:", err);
      setError("Failed to load dashboard data");
    } finally {
      setLoading(false);
    }
  };

  const loadDashboardStats = async () => {
    try {
      const response = await adminAPI.getComprehensiveDashboardStats();
      console.log("Dashboard stats response:", response.data);
      if (response.data.success) {
        setDashboardStats(response.data.stats);
      }
    } catch (err) {
      console.error("Error loading stats:", err);
    }
  };

  const loadPendingReports = async () => {
    try {
      console.log("Loading pending reports from admin API...");
      const response = await adminAPI.getPendingReports();
      console.log("Pending reports response:", response.data);
      
      if (response.data.success) {
        const reports = response.data.reports || [];
        console.log("Total pending reports:", reports.length);
        
        // Filter by status field (lost/found)
        const lost = reports.filter(r => r.status === 'lost');
        const found = reports.filter(r => r.status === 'found');
        
        console.log("Lost reports:", lost.length, "Found reports:", found.length);
        
        setPendingLostReports(lost);
        setPendingFoundReports(found);
      }
    } catch (err) {
      console.error("Error loading pending reports:", err);
      console.error("Error details:", err.response?.data);
    }
  };

  const loadPendingAdoptions = async () => {
    try {
      const response = await adminAPI.filterAdoptionRequests({ status: 'pending' });
      if (response.data.success) {
        setPendingAdoptionRequests(response.data.adoptions || []);
      }
      
      const postsResponse = await adminAPI.getPendingAdoptionPostsNew();
      if (postsResponse.data.success) {
        setPendingAdoptionPosts(postsResponse.data.posts || []);
      }
    } catch (err) {
      console.error("Error loading pending adoptions:", err);
    }
  };

  const loadAllPets = async () => {
    try {
      console.log("Loading all accepted pets...");
      
      // Load all pets by different statuses
      const lostResponse = await adminAPI.getAllPetsByStatus('lost');
      console.log("Lost pets response:", lostResponse.data);
      if (lostResponse.data.success) {
        setAllLostPets(lostResponse.data.pets || []);
        console.log(`✅ Loaded ${lostResponse.data.pets?.length || 0} accepted lost pets`);
      }
      
      const foundResponse = await adminAPI.getAllPetsByStatus('found');
      console.log("Found pets response:", foundResponse.data);
      if (foundResponse.data.success) {
        setAllFoundPets(foundResponse.data.pets || []);
        console.log(`✅ Loaded ${foundResponse.data.pets?.length || 0} accepted found pets`);
      }
      
      const adoptedResponse = await adminAPI.getAllPetsByStatus('adopted');
      console.log("Adopted pets response:", adoptedResponse.data);
      if (adoptedResponse.data.success) {
        setAllAdoptedPets(adoptedResponse.data.pets || []);
        console.log(`✅ Loaded ${adoptedResponse.data.pets?.length || 0} accepted adopted pets`);
      }
      
      const availableResponse = await adminAPI.getAllPetsByStatus('available');
      console.log("Available pets response:", availableResponse.data);
      if (availableResponse.data.success) {
        setAllAvailablePets(availableResponse.data.pets || []);
        console.log(`✅ Loaded ${availableResponse.data.pets?.length || 0} accepted available pets`);
      }
    } catch (err) {
      console.error("Error loading all pets:", err);
    }
  };

  const loadNotifications = async () => {
    try {
      const response = await adminAPI.getNotifications();
      if (response.data.success) {
        const notifs = response.data.notifications || [];
        setNotifications(notifs);
        setUnreadCount(notifs.filter(n => !n.is_read).length);
      }
    } catch (err) {
      console.error("Error loading notifications:", err);
    }
  };

  const handleNotificationClick = async (notification) => {
    console.log("Notification clicked:", notification);
    try {
      // Mark notification as read
      await adminAPI.markNotificationRead(notification.id);
      console.log("Notification marked as read");

      // Update local state
      const updatedNotifications = notifications.map((n) =>
        n.id === notification.id
          ? { ...n, is_read: true }
          : n
      );
      setNotifications(updatedNotifications);

      // Update unread count
      const newUnreadCount = updatedNotifications.filter(
        (n) => !n.is_read
      ).length;
      setUnreadCount(newUnreadCount);

      // Show notification details in modal
      setSelectedNotification({ ...notification, is_read: true });
      setShowNotificationModal(true);
      console.log("Opening modal with notification:", { ...notification, is_read: true });
      setShowNotifications(false); // Close the dropdown
    } catch (err) {
      console.error("Error marking notification as read:", err);
    }
  };

  const handleApproveReport = async (reportId) => {
    try {
      setLoading(true);
      await adminAPI.approveReport(reportId);
      setSuccessMessage("Report approved successfully!");
      await loadAllData();
      setShowDetailModal(false);
    } catch (err) {
      setError(err.response?.data?.error || "Failed to approve report");
    } finally {
      setLoading(false);
    }
  };

  const handleRejectReport = async (reportId) => {
    try {
      setLoading(true);
      await adminAPI.rejectReport(reportId);
      setSuccessMessage("Report rejected successfully!");
      await loadAllData();
      setShowDetailModal(false);
    } catch (err) {
      setError(err.response?.data?.error || "Failed to reject report");
    } finally {
      setLoading(false);
    }
  };

  // Profile Management Functions
  const loadProfile = async () => {
    try {
      const response = await userAPI.getUserDetails();
      if (response.data.success) {
        const userData = response.data.user;
        setProfileData({
          first_name: userData.first_name || "",
          last_name: userData.last_name || "",
          email: userData.email || "",
          phone_no: userData.phone_no || "",
          address: userData.address || "",
          city: userData.city || "",
          state: userData.state || "",
          pincode: userData.pincode || "",
          gender: userData.gender || "",
          profile_picture: userData.profile_picture,
        });

        if (userData.profile_picture) {
          setProfileImagePreview(getImageUrl(userData.profile_picture));
        }
      }
    } catch (err) {
      console.error("Error loading profile:", err);
    }
  };

  const handleProfileImageChange = (e) => {
    const file = e.target.files[0];
    if (file) {
      setProfileImage(file);
      const reader = new FileReader();
      reader.onloadend = () => {
        setProfileImagePreview(reader.result);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleProfileSubmit = async (e) => {
    e.preventDefault();
    setSubmitLoading(true);
    setError("");
    setSuccessMessage("");

    try {
      const formData = new FormData();
      Object.keys(profileData).forEach((key) => {
        if (key !== "profile_picture" && profileData[key]) {
          formData.append(key, profileData[key]);
        }
      });

      if (profileImage) {
        formData.append("profile_picture", profileImage);
      }

      const response = await userAPI.updateProfile(formData);
      if (response.data.success) {
        setSuccessMessage("Profile updated successfully!");
        setIsEditingProfile(false);
        setProfileImage(null); // Reset the file input
        await loadProfile();
      }
    } catch (err) {
      setError(err.response?.data?.error || "Failed to update profile");
    } finally {
      setSubmitLoading(false);
    }
  };

  const handleSearch = async () => {
    setSearchLoading(true);
    setHasSearched(true);
    try {
      const filters = {
        query: searchQuery,
        type: filterType,
        status: filterStatus,
        breed: filterBreed,
        location: filterLocation,
        gender: filterGender,
        report_status: filterReportStatus
      };
      
      console.log("Searching with filters:", filters);
      const response = await adminAPI.searchPets(filters);
      console.log("Search response:", response.data);
      
      if (response.data.success) {
        setSearchResults(response.data.pets || []);
      }
    } catch (err) {
      console.error("Error searching pets:", err);
      setError("Failed to search pets");
      setSearchResults([]);
    } finally {
      setSearchLoading(false);
    }
  };

  const handleProfileInputChange = (e) => {
    const { name, value } = e.target;
    setProfileData((prev) => ({
      ...prev,
      [name]: value,
    }));
  };

  // Load profile when profile tab is active
  useEffect(() => {
    if (activeTab === "profile" && user?.role === 'admin') {
      loadProfile();
    }
  }, [activeTab, user]);

  const handleApproveAdoption = async (adoptionId) => {
    try {
      setLoading(true);
      await adminAPI.approveAdoption(adoptionId);
      setSuccessMessage("Adoption request approved successfully!");
      await loadAllData();
      setShowDetailModal(false);
    } catch (err) {
      setError(err.response?.data?.error || "Failed to approve adoption");
    } finally {
      setLoading(false);
    }
  };

  const handleRejectAdoption = async (adoptionId) => {
    try {
      setLoading(true);
      await adminAPI.rejectAdoption(adoptionId);
      setSuccessMessage("Adoption request rejected successfully!");
      await loadAllData();
      setShowDetailModal(false);
    } catch (err) {
      setError(err.response?.data?.error || "Failed to reject adoption");
    } finally {
      setLoading(false);
    }
  };

  const viewDetails = (item, type) => {
    setSelectedItem(item);
    setModalType(type);
    setShowDetailModal(true);
  };

  const handleLogout = () => {
    logout();
    navigate("/login");
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 to-blue-50">
      {/* Header - Matching UserDashboard Style */}
      <header className="sticky top-0 z-50 backdrop-blur-md bg-gradient-to-r from-slate-50/95 to-blue-50/95 shadow-lg border-b border-blue-200">
        <div className="max-w-full mx-auto px-6 py-4">
          <div className="flex items-center justify-between gap-4">
            <div className="flex items-center gap-3">
              <div className="text-2xl font-bold bg-gradient-to-r from-primary-blue via-primary-teal to-accent-yellow bg-clip-text text-transparent">
                PET_RESCUE_APP - ADMIN
              </div>
            </div>
            <div className="flex-1 text-center">
              <span className="text-lg font-semibold text-primary-blue">
                ADMIN PANEL: {user?.username?.toUpperCase() || "ADMIN"}
              </span>
            </div>
            <div className="flex items-center gap-4">
              {/* Refresh Button */}
              <button
                className="p-2 rounded-full hover:bg-blue-100 transition-all duration-300 disabled:opacity-50"
                onClick={loadAllData}
                disabled={loading}
                title="Refresh Data"
              >
                <span className="material-icons text-primary-blue">
                  refresh
                </span>
              </button>

              {/* Notifications */}
              <div className="relative">
                <button
                  className="p-2 rounded-full hover:bg-blue-100 transition-all duration-300 relative"
                  onClick={() => setShowNotifications(!showNotifications)}
                >
                  <span className="material-icons text-primary-blue">
                    notifications
                  </span>
                  {unreadCount > 0 && !showNotifications && (
                    <span className="absolute -top-1 -right-1 bg-red-500 text-white text-xs font-bold rounded-full w-5 h-5 flex items-center justify-center">
                      {unreadCount}
                    </span>
                  )}
                </button>

                {showNotifications && (
                  <div className="absolute right-0 mt-2 w-96 bg-gradient-to-br from-slate-50 to-blue-50 rounded-2xl shadow-2xl border border-blue-200 overflow-hidden z-50 max-h-[500px] flex flex-col">
                    <div className="flex items-center justify-between p-4 bg-gradient-to-r from-primary-blue to-primary-teal border-b border-blue-200">
                      <h3 className="text-white font-semibold text-lg">
                        Notifications
                      </h3>
                      <button
                        className="text-white hover:bg-white/20 rounded-full p-1 transition-colors"
                        onClick={(e) => {
                          e.stopPropagation();
                          setShowNotifications(false);
                        }}
                      >
                        <span className="text-2xl leading-none">×</span>
                      </button>
                    </div>
                    <div className="overflow-y-auto flex-1">
                      {notifications.length === 0 ? (
                        <div className="flex flex-col items-center justify-center py-12 text-gray-400">
                          <span className="material-icons text-6xl mb-2">
                            notifications_none
                          </span>
                          <p className="text-sm">No notifications yet</p>
                        </div>
                      ) : (
                        notifications.map((notif) => (
                          <div
                            key={notif.id}
                            className={`p-4 border-b border-blue-100 hover:bg-blue-100 transition-colors cursor-pointer ${
                              notif.is_read
                                ? "bg-slate-50"
                                : "bg-blue-50/50"
                            }`}
                            onClick={() => handleNotificationClick(notif)}
                          >
                            <div className="flex items-start justify-between gap-3">
                              <div className="flex-1">
                                <p className={`text-sm ${
                                  notif.is_read
                                    ? "text-gray-600"
                                    : "text-gray-800 font-bold"
                                }`}>
                                  {notif.message}
                                </p>
                                <span className="text-xs text-gray-400 mt-2 block">
                                  {new Date(
                                    notif.created_at
                                  ).toLocaleDateString()}
                                </span>
                              </div>
                            </div>
                          </div>
                        ))
                      )}
                    </div>
                  </div>
                )}
              </div>

              {/* Profile Menu */}
              <div className="relative">
                <button
                  className="w-10 h-10 rounded-full bg-gradient-to-br from-primary-blue to-primary-teal text-white font-bold text-lg flex items-center justify-center hover:shadow-lg transition-all duration-300 hover:scale-110"
                  onClick={() => setShowProfileDropdown((prev) => !prev)}
                >
                  {user?.username?.charAt(0).toUpperCase() || "A"}
                </button>
                {showProfileDropdown && (
                  <div className="absolute right-0 mt-2 w-48 bg-gradient-to-br from-slate-50 to-blue-50 rounded-xl shadow-xl border border-blue-200 overflow-hidden z-50">
                    <button
                      className="w-full px-4 py-3 text-left hover:bg-blue-100 transition-colors text-gray-700 hover:text-primary-blue font-medium"
                      onClick={() => {
                        setActiveTab("profile");
                        setShowProfileDropdown(false);
                      }}
                    >
                      Edit Profile
                    </button>
                    <button
                      className="w-full px-4 py-3 text-left hover:bg-red-50 transition-colors text-red-600 hover:text-red-700 font-medium border-t border-gray-100"
                      onClick={() => {
                        localStorage.removeItem("token");
                        window.location.href = "/login";
                      }}
                    >
                      Logout
                    </button>
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
      </header>

      {/* Success/Error Messages */}
      {error && (
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 mt-4">
          <div className="bg-red-100 border-l-4 border-red-500 text-red-700 p-4 rounded-lg shadow-lg animate-slideUp">
            <p className="font-bold">Error</p>
            <p>{error}</p>
          </div>
        </div>
      )}

      {successMessage && (
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 mt-4">
          <div className="bg-green-100 border-l-4 border-green-500 text-green-700 p-4 rounded-lg shadow-lg animate-slideUp">
            <p className="font-bold">Success</p>
            <p>{successMessage}</p>
          </div>
        </div>
      )}

      {/* Main Content Container */}
      <div className="overflow-y-auto" style={{ height: "calc(100vh - 100px)" }}>
        {/* Horizontal Navigation Bar - Full Width */}
        <nav className="bg-gradient-to-r from-primary-blue via-primary-teal to-primary-teal border-t border-blue-200">
          <ul className="flex items-center justify-center gap-1 px-4 max-w-7xl mx-auto overflow-x-auto">
            <li
              className={`flex items-center gap-2 px-4 py-4 cursor-pointer transition-all duration-300 whitespace-nowrap ${
                activeTab === "dashboard"
                  ? "bg-white/20 border-b-4 border-accent-yellow text-white"
                  : "text-white/80 hover:bg-white/10 hover:text-white"
              }`}
              onClick={() => setActiveTab("dashboard")}
            >
              <span className="material-icons text-lg">dashboard</span>
              <span className="font-semibold text-xs">DASHBOARD</span>
            </li>
            <li
              className={`flex items-center gap-2 px-4 py-4 cursor-pointer transition-all duration-300 whitespace-nowrap ${
                activeTab === "pending-requests"
                  ? "bg-white/20 border-b-4 border-accent-yellow text-white"
                  : "text-white/80 hover:bg-white/10 hover:text-white"
              }`}
              onClick={() => setActiveTab("pending-requests")}
            >
              <span className="material-icons text-lg">pending_actions</span>
              <span className="font-semibold text-xs">PENDING REQUESTS</span>
            </li>
            <li
              className={`flex items-center gap-2 px-4 py-4 cursor-pointer transition-all duration-300 whitespace-nowrap ${
                activeTab === "all-records"
                  ? "bg-white/20 border-b-4 border-accent-yellow text-white"
                  : "text-white/80 hover:bg-white/10 hover:text-white"
              }`}
              onClick={() => setActiveTab("all-records")}
            >
              <span className="material-icons text-lg">storage</span>
              <span className="font-semibold text-xs">ALL RECORDS</span>
            </li>
            <li
              className={`flex items-center gap-2 px-4 py-4 cursor-pointer transition-all duration-300 whitespace-nowrap ${
                activeTab === "available-pets"
                  ? "bg-white/20 border-b-4 border-accent-yellow text-white"
                  : "text-white/80 hover:bg-white/10 hover:text-white"
              }`}
              onClick={() => setActiveTab("available-pets")}
            >
              <span className="material-icons text-lg">pets</span>
              <span className="font-semibold text-xs">AVAILABLE PETS</span>
            </li>
            <li
              className={`flex items-center gap-2 px-4 py-4 cursor-pointer transition-all duration-300 whitespace-nowrap ${
                activeTab === "search"
                  ? "bg-white/20 border-b-4 border-accent-yellow text-white"
                  : "text-white/80 hover:bg-white/10 hover:text-white"
              }`}
              onClick={() => setActiveTab("search")}
            >
              <span className="material-icons text-lg">search</span>
              <span className="font-semibold text-xs">SEARCH</span>
            </li>
            <li
              className={`flex items-center gap-2 px-4 py-4 cursor-pointer transition-all duration-300 whitespace-nowrap ${
                activeTab === "notifications"
                  ? "bg-white/20 border-b-4 border-accent-yellow text-white"
                  : "text-white/80 hover:bg-white/10 hover:text-white"
              }`}
              onClick={() => setActiveTab("notifications")}
            >
              <span className="material-icons text-lg">notifications</span>
              <span className="font-semibold text-xs">NOTIFICATIONS</span>
            </li>
          </ul>
        </nav>

        <div className="max-w-7xl mx-auto px-6 py-8">
          <main>
            {error && (
              <div className="bg-red-50 border-l-4 border-red-500 p-4 mb-6 rounded-r-lg">
                <p className="text-red-700 font-medium">{error}</p>
              </div>
            )}
            {successMessage && (
              <div className="bg-green-50 border-l-4 border-green-500 p-4 mb-6 rounded-r-lg">
                <p className="text-green-700 font-medium">{successMessage}</p>
              </div>
            )}

            {/* Dashboard Overview */}
            {activeTab === "dashboard" && (
              <div className="bg-gradient-to-br from-slate-50 to-blue-50 rounded-2xl shadow-xl p-8 border border-blue-100">
                <h2 className="text-2xl font-bold mb-6 flex items-center gap-3">
                  <span className="material-icons text-3xl text-primary-blue">dashboard</span>
                  <span className="bg-gradient-to-r from-primary-blue via-primary-teal to-accent-yellow bg-clip-text text-transparent">
                    DASHBOARD OVERVIEW
                  </span>
                </h2>

                {/* Stats Grid */}
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
                  {/* Pending Requests */}
                  <div className="bg-gradient-to-br from-orange-50 to-orange-100 rounded-xl p-6 border border-orange-200 hover:shadow-lg transition-shadow cursor-pointer" onClick={() => setActiveTab("pending-requests")}>
                    <div className="flex items-center justify-between mb-2">
                      <span className="material-icons text-4xl text-orange-600">pending_actions</span>
                      <span className="text-3xl font-bold text-orange-600">
                        {dashboardStats?.pending?.total || (pendingLostReports.length + pendingFoundReports.length + pendingAdoptionRequests.length + pendingAdoptionPosts.length)}
                      </span>
                    </div>
                    <h3 className="text-sm font-semibold text-gray-600 uppercase tracking-wide">
                      Total Pending Requests
                    </h3>
                    <p className="text-xs text-gray-500 mt-2">
                      Lost: {dashboardStats?.pending?.lost_reports || pendingLostReports.length} | 
                      Found: {dashboardStats?.pending?.found_reports || pendingFoundReports.length}
                    </p>
                  </div>

                  {/* Lost Pets (Accepted Only) */}
                  <div className="bg-gradient-to-br from-red-50 to-red-100 rounded-xl p-6 border border-red-200 hover:shadow-lg transition-shadow cursor-pointer" onClick={() => { setActiveTab("all-records"); setActiveRecordsTab("all-lost"); }}>
                    <div className="flex items-center justify-between mb-2">
                      <span className="material-icons text-4xl text-red-600">search</span>
                      <span className="text-3xl font-bold text-red-600">
                        {dashboardStats?.accepted?.lost || allLostPets.length}
                      </span>
                    </div>
                    <h3 className="text-sm font-semibold text-gray-600 uppercase tracking-wide">
                      Lost Pets (Accepted)
                    </h3>
                  </div>

                  {/* Found Pets (Accepted Only) */}
                  <div className="bg-gradient-to-br from-green-50 to-green-100 rounded-xl p-6 border border-green-200 hover:shadow-lg transition-shadow cursor-pointer" onClick={() => { setActiveTab("all-records"); setActiveRecordsTab("all-found"); }}>
                    <div className="flex items-center justify-between mb-2">
                      <span className="material-icons text-4xl text-green-600">pets</span>
                      <span className="text-3xl font-bold text-green-600">
                        {dashboardStats?.accepted?.found || allFoundPets.length}
                      </span>
                    </div>
                    <h3 className="text-sm font-semibold text-gray-600 uppercase tracking-wide">
                      Found Pets (Accepted)
                    </h3>
                  </div>

                  {/* Adopted Pets */}
                  <div className="bg-gradient-to-br from-purple-50 to-purple-100 rounded-xl p-6 border border-purple-200 hover:shadow-lg transition-shadow cursor-pointer" onClick={() => { setActiveTab("all-records"); setActiveRecordsTab("all-adopted"); }}>
                    <div className="flex items-center justify-between mb-2">
                      <span className="material-icons text-4xl text-purple-600">favorite</span>
                      <span className="text-3xl font-bold text-purple-600">
                        {dashboardStats?.accepted?.adopted || allAdoptedPets.length}
                      </span>
                    </div>
                    <h3 className="text-sm font-semibold text-gray-600 uppercase tracking-wide">
                      Adopted Pets
                    </h3>
                  </div>

                  {/* Available for Adoption */}
                  <div className="bg-gradient-to-br from-pink-50 to-pink-100 rounded-xl p-6 border border-pink-200 hover:shadow-lg transition-shadow cursor-pointer" onClick={() => { setActiveTab("all-records"); setActiveRecordsTab("available"); }}>
                    <div className="flex items-center justify-between mb-2">
                      <span className="material-icons text-4xl text-pink-600">home</span>
                      <span className="text-3xl font-bold text-pink-600">
                        {dashboardStats?.accepted?.available || allAvailablePets.length}
                      </span>
                    </div>
                    <h3 className="text-sm font-semibold text-gray-600 uppercase tracking-wide">
                      Available for Adoption
                    </h3>
                  </div>

                  {/* Total Pets */}
                  <div className="bg-gradient-to-br from-blue-50 to-blue-100 rounded-xl p-6 border border-blue-200 hover:shadow-lg transition-shadow">
                    <div className="flex items-center justify-between mb-2">
                      <span className="material-icons text-4xl text-primary-blue">storage</span>
                      <span className="text-3xl font-bold text-primary-blue">
                        {dashboardStats?.totals?.pets || 0}
                      </span>
                    </div>
                    <h3 className="text-sm font-semibold text-gray-600 uppercase tracking-wide">
                      Total Pets
                    </h3>
                  </div>

                  {/* Total Reports */}
                  <div className="bg-gradient-to-br from-teal-50 to-teal-100 rounded-xl p-6 border border-teal-200 hover:shadow-lg transition-shadow">
                    <div className="flex items-center justify-between mb-2">
                      <span className="material-icons text-4xl text-primary-teal">description</span>
                      <span className="text-3xl font-bold text-primary-teal">
                        {dashboardStats?.totals?.reports || 0}
                      </span>
                    </div>
                    <h3 className="text-sm font-semibold text-gray-600 uppercase tracking-wide">
                      Total Reports
                    </h3>
                  </div>

                  {/* Total Adoptions */}
                  <div className="bg-gradient-to-br from-indigo-50 to-indigo-100 rounded-xl p-6 border border-indigo-200 hover:shadow-lg transition-shadow">
                    <div className="flex items-center justify-between mb-2">
                      <span className="material-icons text-4xl text-indigo-600">assignment_turned_in</span>
                      <span className="text-3xl font-bold text-indigo-600">
                        {dashboardStats?.totals?.adoptions || 0}
                      </span>
                    </div>
                    <h3 className="text-sm font-semibold text-gray-600 uppercase tracking-wide">
                      Total Adoptions
                    </h3>
                  </div>
                </div>

                {/* Quick Actions */}
                <div className="bg-white rounded-xl p-6 border border-blue-200">
                  <h3 className="text-xl font-bold text-gray-800 mb-4 flex items-center gap-2">
                    <span className="material-icons text-primary-blue">flash_on</span>
                    Quick Actions
                  </h3>
                  <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                    <button
                      onClick={() => setActiveTab("pending-reports")}
                      className="flex items-center gap-3 px-4 py-3 bg-gradient-to-r from-primary-blue to-primary-teal text-white rounded-xl hover:shadow-lg transform hover:scale-105 transition-all duration-200"
                    >
                      <span className="material-icons">pending_actions</span>
                      <span className="font-semibold">View Reports</span>
                    </button>
                    <button
                      onClick={() => { 
                        setActiveTab("all-records"); 
                        setActiveRecordsTab("all-adopted"); 
                      }}
                      className="flex items-center gap-3 px-4 py-3 bg-gradient-to-r from-teal-500 to-teal-600 text-white rounded-xl hover:shadow-lg transform hover:scale-105 transition-all duration-200"
                    >
                      <span className="material-icons">home</span>
                      <span className="font-semibold">Adoptions</span>
                    </button>
                    <button
                      onClick={() => setActiveTab("all-pets")}
                      className="flex items-center gap-3 px-4 py-3 bg-gradient-to-r from-purple-500 to-purple-600 text-white rounded-xl hover:shadow-lg transform hover:scale-105 transition-all duration-200"
                    >
                      <span className="material-icons">pets</span>
                      <span className="font-semibold">All Pets</span>
                    </button>
                    <button
                      onClick={() => setActiveTab("search")}
